import"./modulepreload-polyfill-3cfb730f.js";/* empty css              */import{s as r}from"./supabase-b7fcd0c7.js";let i=[];document.addEventListener("DOMContentLoaded",async()=>{if(sessionStorage.getItem("aztec_key")!=="buka_sesame")return window.location.replace("/dashboard.html");l(),document.querySelectorAll(".btn-close").forEach(t=>t.onclick=()=>document.getElementById("modalReview").classList.add("hidden"))});async function l(){const t=document.getElementById("approvalTableBody");try{const{data:s,error:o}=await r.from("sponsor_submissions").select("*, events(event_name), master_sponsors(sponsor_name)").eq("status","Menunggu Review").order("created_at",{ascending:!1});if(o)throw o;if(i=s||[],i.length===0){t.innerHTML='<tr><td colspan="4" class="p-6 text-center text-slate-500 font-bold">Yeay! Tidak ada antrian proposal.</td></tr>';return}let n="";i.forEach(e=>{const d=e.events?e.events.event_name:"Event ID: "+e.event_id,a=e.master_sponsors?e.master_sponsors.sponsor_name:"Sponsor ID: "+e.sponsor_id,c=encodeURIComponent(JSON.stringify(e));n+=`
                <tr class="hover:bg-slate-800/50 transition-colors">
                    <td class="p-4 font-bold text-white">${d}</td>
                    <td class="p-4 font-black text-amber-400">${a}</td>
                    <td class="p-4 text-center"><span class="bg-amber-900/50 text-amber-500 px-3 py-1 rounded text-[10px] font-bold border border-amber-500/30">⏳ Menunggu</span></td>
                    <td class="p-4 text-center">
                        <button onclick="openReview('${c}', '${d}', '${a}')" class="bg-blue-600 hover:bg-blue-500 text-white font-bold py-1.5 px-4 rounded-lg text-xs transition shadow">Review & Approve</button>
                    </td>
                </tr>
            `}),t.innerHTML=n}catch(s){t.innerHTML=`<tr><td colspan="4" class="p-6 text-center text-red-500 font-bold">Error: ${s.message}</td></tr>`}}window.openReview=function(t,s,o){const n=JSON.parse(decodeURIComponent(t));document.getElementById("revSubId").value=n.id,document.getElementById("revEventId").value=n.event_id,document.getElementById("revSponsorId").value=n.sponsor_id,document.getElementById("revEventName").innerText=s,document.getElementById("revBrandName").innerText=o,document.getElementById("revSupportType").innerText=n.support_type_req||"-",document.getElementById("revBenefits").innerText=n.benefits_offered||"-",document.getElementById("revNotes").innerText=n.proposal_note||"-",document.getElementById("modalReview").classList.remove("hidden")};document.getElementById("btnApprove").addEventListener("click",async()=>{const t=document.getElementById("revSubId").value,s=document.getElementById("revEventId").value,o=parseInt(document.getElementById("revSponsorId").value),n=document.getElementById("revJenisDeal").value,e=document.getElementById("btnApprove");e.innerText="⏳ Memproses...",e.disabled=!0;try{await r.from("sponsor_submissions").update({status:"Disetujui",jenis_bantuan_deal:n}).eq("id",t);const{data:d}=await r.from("event_sponsors").select("*").eq("event_id",s).single();if(d){let a=d.sponsor_ids||[];a.includes(o)||(a.push(o),await r.from("event_sponsors").update({sponsor_ids:a}).eq("id",d.id))}else await r.from("event_sponsors").insert([{event_id:s,sponsor_ids:[o]}]);document.getElementById("modalReview").classList.add("hidden"),l()}catch(d){alert("Gagal Approve: "+d.message)}finally{e.innerText="✅ APPROVE & TAYANGKAN LOGO",e.disabled=!1}});window.tolakProposal=async function(){const t=document.getElementById("revSubId").value;if(confirm("Yakin menolak proposal ini?"))try{await r.from("sponsor_submissions").update({status:"Ditolak"}).eq("id",t),document.getElementById("modalReview").classList.add("hidden"),l()}catch(s){alert(s.message)}};
